SELECT MIN("Uberlandia_1"."data_de_inicio") AS "TEMP_attr_data_de_inicio_ok__3982078387__0_",   MAX("Uberlandia_1"."data_de_inicio") AS "TEMP_attr_data_de_inicio_ok__86782374__0_",   MIN("Uberlandia_1"."data_de_previsaode_termino") AS "TEMP_attr_data_de_previsaode_termino_ok__4171852708__0_",   MAX("Uberlandia_1"."data_de_previsaode_termino") AS "TEMP_attr_data_de_previsaode_termino_ok__570103144__0_",   CAST("Uberlandia_1"."codigo_da_oferta" AS BIGINT) AS "codigo_da_oferta",   "Uberlandia_1"."edicao_catalogo_guia" AS "edicao_catalogo_guia",   "Uberlandia_1"."nome_do_curso" AS "nome_do_curso",   "Uberlandia_1"."situacao_da_turma" AS "situacao_da_turma",   "Uberlandia_1"."subtipo_curso" AS "subtipo_curso",   SUM(CAST("Uberlandia_1"."Number_of_Records" AS BIGINT)) AS "sum_Number_of_Records_ok",   CAST(EXTRACT(YEAR FROM "Uberlandia_1"."data_de_inicio") AS BIGINT) AS "yr_data_de_inicio_ok" FROM "Uberlandia_1" WHERE (("Uberlandia_1"."nome_do_curso" IN ('Agente de Saúde e Bem estar Animal', 'Eletricista de Veículos de Transporte de Cargas e de Passageiros', 'Recepcionista em Meios de Hospedagem', 'RECEPCIONISTA EM MEIOS DE HOSPEDAGEM', 'Soldador no Processo MIG/MAG', 'SOLDADOR NO PROCESSO MIG/MAG', 'Traçador de Caldeiraria', 'TRAÇADOR DE CALDEIRARIA')) AND (NOT ("Uberlandia_1"."situacao_da_turma" IN ('CANCELADA', 'CRIADA', 'PUBLICADA'))) AND ("Uberlandia_1"."subtipo_curso" = 'FIC') AND (CAST(EXTRACT(YEAR FROM "Uberlandia_1"."data_de_inicio") AS BIGINT) = 2015) AND (NOT (("Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_" NOT IN ('', 'TRANSF_EXT', 'INTEGRALIZADA', 'FREQ_INIC_INSUF', 'TRANCADA', 'CONCLUÍDA', 'TRANSF_INT', 'EM_CURSO', 'REPROVADA', 'ABANDONO', 'CONFIRMADA', 'EM_DEPENDÊNCIA')) OR ("Uberlandia_1"."nome_da_sit_matricula__situacao_detalhada_" IS NULL)))) GROUP BY "Uberlandia_1"."codigo_da_oferta",   "edicao_catalogo_guia",   "nome_do_curso",   "situacao_da_turma",   "subtipo_curso",   "yr_data_de_inicio_ok",   "codigo_da_oferta";
